import json
import sqlite3
from pathlib import Path

records = json.loads(Path('/tmp/cat218-feed.json').read_text())
with sqlite3.connect('/tmp/catalog-before-cat218.db') as before, sqlite3.connect('data/catalog.db') as after:
    original = {r[0]: r for r in before.execute('SELECT * FROM products')}
    current = {r[0]: r for r in after.execute('SELECT * FROM products')}
    seen = {r['sku'] for r in records}
    for record in records:
        sku = record['sku']
        if record.get('deleted'):
            assert sku not in current, sku
        else:
            assert current[sku] == (sku, record['name'], record['price_paise'], 'vendor', record['updated_at']), sku
    for sku, row in original.items():
        if row[3] == 'manual' or sku not in seen:
            assert current[sku] == row, sku
    assert after.execute('PRAGMA integrity_check').fetchone() == ('ok',)
    print('Verified all 260 live records and 8 tombstones; manual and unmentioned rows unchanged.')
    print('Counts:', after.execute('SELECT source, COUNT(*) FROM products GROUP BY source').fetchall())
    print('Sync state:', after.execute('SELECT * FROM sync_state').fetchall())
